def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def DEM(t):return f'<p><b>Демек: {t}</b></p>'
def N(x,y,n):return f'<circle cx="{x}" cy="{y}" r="8" class="bxa"/>'+T(x,y+4,str(n),'t-s t-b')

# ---------- numbers, recomputed ----------
assert 200+100==300 and 300-256==44 and 2**8-1==255 and format(200,'08b')=='11001000' and format(100,'08b')=='01100100'
assert format(44,'08b')=='00101100'                              # 200+100 low byte; CF=1, SF=0, ZF=0
assert (200+100)&0xFF==44 and bin(44).count('1')==3              # PF: 3 ones -> odd -> PF=0
assert (200&0xF)+(100&0xF)==12 and 12<16                         # AF=0 for 200+100 (low nibbles 8+4)
s=100+100
assert s==200 and format(s,'08b')=='11001000' and s<256         # CF=0
assert s>127 and s-256==-56                                      # signed: overflow, reads as -56 -> OF=1, SF=1
assert bin(s).count('1')==3 and (100&0xF)+(100&0xF)==8 and 8<16 # PF=0, AF=0
assert 200-256==-56 and -56+100==44 and -128<=44<=127           # 200+100 signed: no overflow, OF=0
assert 127+1==128 and 128>127 and 128<256                       # check: CF=0, OF=1, SF=1
assert 5-5==0
assert 2**16==65536 and 65536//1024==64 and 2**20==1048576 and 1048576//2**20==1 and 2**32//2**30==4
assert 2**12==4096 and 4096//1024==4 and 2*2**20==2097152
assert -(-16//8)==2 and -(-32//8)==4 and -(-32//16)==2         # cycles: 16 bit via 8 -> 2; 32 via 8 -> 4; 32 via 16 -> 2
assert 0x0100+3==0x0103 and 0x200==512 and 0xC8==200 and 0x64==100
assert 0x1000*16==0x10000 and 0x10000+0x20==0x10020
assert 0x2000*16+0x100==0x20100 and 0x2010*16+0==0x20100 and 0x1002*16==0x10020
assert 6//3==2 and -(-3//8)==1 and 3*8==24
assert 16*16==2**8 and 2**4==16

